-- PostgreSQL baseline for the frozen SQLite schema. No business data is imported here.
-- _order preserves historical insertion order explicitly; step 4 imports its old rowid.

CREATE TABLE schema_metadata ( key TEXT PRIMARY KEY, value INTEGER NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE projects ( id TEXT PRIMARY KEY, title TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE conversations ( id TEXT PRIMARY KEY, title TEXT NOT NULL, project_id TEXT REFERENCES projects(id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE conversation_messages ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), mode TEXT NOT NULL CHECK (mode IN ('chat', 'work')), content TEXT NOT NULL, created_at TEXT NOT NULL , submission_key TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE tasks ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), objective TEXT NOT NULL, project_id TEXT REFERENCES projects(id), status TEXT NOT NULL CHECK (status IN ('created')), created_at TEXT NOT NULL , message_id TEXT REFERENCES conversation_messages(id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE identity_roles ( id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, system INTEGER NOT NULL CHECK (system IN (0, 1)) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE identity_users ( id TEXT PRIMARY KEY, username TEXT NOT NULL, display_name TEXT NOT NULL, department TEXT, password_salt BYTEA NOT NULL, password_hash BYTEA NOT NULL, is_active INTEGER NOT NULL CHECK (is_active IN (0, 1)), created_at TEXT NOT NULL , access_level INTEGER NOT NULL DEFAULT 1 CHECK (access_level BETWEEN 1 AND 5), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE identity_user_roles ( user_id TEXT NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES identity_roles(id), PRIMARY KEY (user_id, role_id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE identity_sessions ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE authorization_role_permissions (role_id TEXT NOT NULL, permission_id TEXT NOT NULL, PRIMARY KEY (role_id, permission_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE authorization_field_policies (field_id TEXT PRIMARY KEY, read_role_ids TEXT NOT NULL DEFAULT '[]', write_role_ids TEXT NOT NULL DEFAULT '[]', read_min_level INTEGER NOT NULL DEFAULT 4, write_min_level INTEGER NOT NULL DEFAULT 4, read_scope_ids TEXT NOT NULL DEFAULT '[]', write_scope_ids TEXT NOT NULL DEFAULT '[]', _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE authorization_audit_events (id TEXT PRIMARY KEY, actor_user_id TEXT, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE knowledge_sources ( id TEXT PRIMARY KEY, filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, stored_name TEXT NOT NULL UNIQUE, legacy_storage_status TEXT NOT NULL DEFAULT 'quarantined' CHECK (legacy_storage_status IN ('quarantined')), duplicate_of TEXT REFERENCES knowledge_sources(id), created_by_user_id TEXT NOT NULL REFERENCES identity_users(id), created_at TEXT NOT NULL , processing_status TEXT NOT NULL DEFAULT 'not_started', processing_error TEXT, safety_status TEXT NOT NULL DEFAULT 'quarantined' CHECK(safety_status IN ('quarantined','confirmed')), read_min_level INTEGER NOT NULL DEFAULT 4, read_scope_ids TEXT NOT NULL DEFAULT '[]', _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE knowledge_source_read_roles ( source_id TEXT NOT NULL REFERENCES knowledge_sources(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES identity_roles(id), PRIMARY KEY (source_id, role_id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE knowledge_versions ( id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES knowledge_sources(id), stored_name TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('draft')), created_by_user_id TEXT NOT NULL REFERENCES identity_users(id), created_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE knowledge_version_sources ( version_id TEXT NOT NULL REFERENCES knowledge_versions(id) ON DELETE CASCADE, source_id TEXT NOT NULL REFERENCES knowledge_sources(id), PRIMARY KEY (version_id, source_id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE authorization_custom_fields (id TEXT PRIMARY KEY, area TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, UNIQUE (area, name), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE identity_user_scopes ( user_id TEXT NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE, scope_id TEXT NOT NULL, access_level INTEGER NOT NULL DEFAULT 1 CHECK (access_level BETWEEN 1 AND 4), PRIMARY KEY (user_id, scope_id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_materials ( id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, unit TEXT NOT NULL, latest_price TEXT, inventory_price TEXT, in_transit_price TEXT, previous_latest_price TEXT, last_import_id TEXT, updated_at TEXT NOT NULL , archived_at TEXT, archived_by TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_imports ( id TEXT PRIMARY KEY, source_name TEXT NOT NULL, received_count INTEGER NOT NULL, imported_count INTEGER NOT NULL, skipped_count INTEGER NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL , effective_date TEXT, archived_at TEXT, archived_by TEXT, update_id TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_issues ( id TEXT PRIMARY KEY, material_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('open', 'reviewed', 'resolved')), created_at TEXT NOT NULL, reviewed_by TEXT, reviewed_at TEXT , update_id TEXT, review_reason TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_price_history ( id TEXT PRIMARY KEY, material_id TEXT NOT NULL, import_id TEXT NOT NULL, latest_price TEXT, inventory_price TEXT, in_transit_price TEXT, recorded_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_price_batches ( id TEXT PRIMARY KEY, version INTEGER NOT NULL UNIQUE, published_by TEXT NOT NULL, published_at TEXT NOT NULL, item_count INTEGER NOT NULL , update_id TEXT, price_date TEXT, activated_at TEXT, submitted_by TEXT, source_name TEXT, base_batch_id TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_price_batch_items ( batch_id TEXT NOT NULL, material_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, latest_price TEXT, inventory_price TEXT, in_transit_price TEXT, recommended_price TEXT, PRIMARY KEY (batch_id, material_id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_working_state ( id INTEGER PRIMARY KEY CHECK (id = 1), latest_import_id TEXT, submitted_by TEXT, submitted_at TEXT , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_price_adjustments ( id TEXT PRIMARY KEY, material_id TEXT NOT NULL, target_history_id TEXT, replacement_history_id TEXT NOT NULL UNIQUE, reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL , update_id TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_user_preferences ( user_id TEXT PRIMARY KEY, ledger_columns TEXT NOT NULL, history_view TEXT NOT NULL CHECK (history_view IN ('batches', 'materials')), updated_at TEXT NOT NULL , ledger_view TEXT NOT NULL DEFAULT 'scroll' CHECK (ledger_view IN ('scroll', 'paged')), ledger_page_size INTEGER NOT NULL DEFAULT 50 CHECK (ledger_page_size BETWEEN 10 AND 200), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_material_aliases ( alias_code TEXT PRIMARY KEY, material_id TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_material_identity_changes ( id TEXT PRIMARY KEY, material_id TEXT NOT NULL, old_code TEXT NOT NULL, new_code TEXT NOT NULL, old_name TEXT NOT NULL, new_name TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_updates ( id TEXT PRIMARY KEY, price_date TEXT NOT NULL, source_name TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ( 'draft', 'returned', 'submitted', 'scheduled', 'revalidation_required', 'published', 'cancelled' )), submitted_by TEXT, submitted_at TEXT, return_reason TEXT, scheduled_activate_at TEXT, base_batch_id TEXT, published_batch_id TEXT, cancelled_by TEXT, cancelled_at TEXT, cancel_reason TEXT , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_update_items ( update_id TEXT NOT NULL, material_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, latest_price TEXT, inventory_price TEXT, in_transit_price TEXT, recommended_price TEXT, PRIMARY KEY (update_id, material_id) , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_update_events ( id TEXT PRIMARY KEY, update_id TEXT NOT NULL, event TEXT NOT NULL, actor_user_id TEXT, reason TEXT, created_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_departments (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, position INTEGER NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_department_materials ( department_id TEXT NOT NULL, material_id TEXT NOT NULL, PRIMARY KEY(department_id, material_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_activation_grants ( user_id TEXT PRIMARY KEY, manager INTEGER NOT NULL DEFAULT 0, granted_by TEXT NOT NULL, granted_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_admin_events ( id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_saved_changes ( event_id TEXT NOT NULL, update_id TEXT NOT NULL, material_id TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, before_price TEXT, after_price TEXT, price_date TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(event_id, material_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_source_imports ( sha256 TEXT PRIMARY KEY, filename TEXT NOT NULL, stored_path TEXT NOT NULL, imported_by TEXT NOT NULL, imported_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_material_sources ( material_id TEXT NOT NULL, sheet TEXT NOT NULL, source_row INTEGER NOT NULL, raw_json TEXT NOT NULL, sha256 TEXT NOT NULL, PRIMARY KEY(material_id, sheet, source_row, sha256), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_batch_provenance ( batch_id TEXT PRIMARY KEY, origin TEXT NOT NULL, sha256 TEXT, imported_at TEXT, imported_by TEXT, reported_count INTEGER NOT NULL DEFAULT 0, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_snapshot_sources ( batch_id TEXT NOT NULL, material_id TEXT NOT NULL, price_date TEXT, raw_price TEXT, price_kind TEXT NOT NULL, sheet TEXT, cell TEXT, sha256 TEXT, PRIMARY KEY(batch_id, material_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE identity_password_failures (user_id TEXT NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE, attempted_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE feedback ( id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, owner_name TEXT NOT NULL, kind TEXT NOT NULL, text TEXT NOT NULL, context TEXT NOT NULL, version TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT '待处理', result TEXT NOT NULL DEFAULT '', result_at TEXT, revision INTEGER NOT NULL DEFAULT 1, result_revision INTEGER NOT NULL DEFAULT 0, image BYTEA, image_mime TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE feedback_reads ( feedback_id TEXT NOT NULL, user_id TEXT NOT NULL, revision INTEGER NOT NULL, PRIMARY KEY (feedback_id, user_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE organization_departments ( id TEXT PRIMARY KEY, name TEXT NOT NULL, parent_id TEXT REFERENCES organization_departments(id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE organization_memberships ( user_id TEXT NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE, department_id TEXT NOT NULL REFERENCES organization_departments(id), is_primary INTEGER NOT NULL CHECK(is_primary IN (0,1)), PRIMARY KEY(user_id,department_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE "procurement_inventory" ( material_id TEXT PRIMARY KEY REFERENCES procurement_materials(id), quantity TEXT, price TEXT, raw_price TEXT NOT NULL, source_sha256 TEXT NOT NULL, sheet TEXT NOT NULL, source_row INTEGER NOT NULL, imported_by TEXT NOT NULL, imported_at TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE procurement_rd5_imports ( sha256 TEXT PRIMARY KEY, imported_by TEXT NOT NULL, imported_at TEXT NOT NULL, result_json TEXT NOT NULL, package_json TEXT NOT NULL , _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_meta(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_formulas(id TEXT PRIMARY KEY,position INTEGER NOT NULL,revision INTEGER NOT NULL,formula TEXT NOT NULL,draft_sequence INTEGER NOT NULL DEFAULT 0, lifecycle TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','draft','inactive')), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_formula_versions(id TEXT NOT NULL,revision INTEGER NOT NULL,formula TEXT NOT NULL,actor TEXT,recorded_at TEXT NOT NULL,PRIMARY KEY(id,revision), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_drafts(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,formula TEXT NOT NULL,simulation_token TEXT NOT NULL,actor TEXT NOT NULL,updated_at TEXT NOT NULL, simulation TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_events(id TEXT PRIMARY KEY,recorded_at TEXT NOT NULL,reason TEXT NOT NULL,inputs TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL,error TEXT, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_cost_records(sequence BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id TEXT NOT NULL,product_id TEXT NOT NULL,signature TEXT NOT NULL,payload TEXT NOT NULL,UNIQUE(event_id,product_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_backfill_runs(id INTEGER PRIMARY KEY CHECK(id=1),recorded_at TEXT NOT NULL,inputs TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_backfill_records(purchase_version INTEGER NOT NULL,product_id TEXT NOT NULL,signature TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(purchase_version,product_id), _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_activation_grants (user_id TEXT PRIMARY KEY, manager INTEGER NOT NULL DEFAULT 0, granted_by TEXT NOT NULL, granted_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE research_admin_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL, _order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE UNIQUE INDEX conversation_messages_submission_key ON conversation_messages(submission_key) WHERE submission_key IS NOT NULL;

CREATE UNIQUE INDEX tasks_message_id ON tasks(message_id) WHERE message_id IS NOT NULL;

CREATE UNIQUE INDEX procurement_open_issue ON procurement_issues(material_id, kind) WHERE status = 'open';

CREATE UNIQUE INDEX procurement_adjustment_target ON procurement_price_adjustments(target_history_id) WHERE target_history_id IS NOT NULL;

CREATE INDEX procurement_material_alias_material ON procurement_material_aliases(material_id);

CREATE INDEX procurement_updates_status ON procurement_updates(status, updated_at DESC);

CREATE INDEX procurement_update_events_update ON procurement_update_events(update_id, created_at DESC);

CREATE INDEX identity_password_failures_account ON identity_password_failures(user_id, attempted_at);

CREATE INDEX feedback_owner ON feedback(owner_id);

CREATE UNIQUE INDEX organization_sibling_name ON organization_departments(COALESCE(parent_id, ''), translate(name,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'));

CREATE UNIQUE INDEX organization_one_primary ON organization_memberships(user_id) WHERE is_primary=1;

CREATE INDEX research_product_history ON research_cost_records(product_id,sequence);

CREATE UNIQUE INDEX research_formula_name ON research_formulas(translate(trim(formula::jsonb ->> 'name'),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'));

CREATE VIEW knowledge_derived_index AS SELECT versions.id AS version_id, links.source_id, sources.filename, sources.sha256 FROM knowledge_versions AS versions JOIN knowledge_version_sources AS links ON links.version_id = versions.id JOIN knowledge_sources AS sources ON sources.id = links.source_id;

CREATE UNIQUE INDEX identity_username ON identity_users(translate(username,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'));

INSERT INTO schema_metadata(key,value) VALUES ('schema_version',5),('identity_schema_version',6),('authorization_schema_version',5),('knowledge_schema_version',6),('workbench_procurement_schema_version',7),('organization_schema_version',1),('workbench_research_schema_version',2);

